88	
89	/// Error type for all OAuth-related operations.
90	///
91	/// Variants serialize as `{ "code": "SCREAMING_SNAKE_CASE" }` to match the
92	/// existing error pattern (`CreateAccountError`, `DeviceKeyError`, etc.).
93	#[derive(Debug, thiserror::Error, serde::Serialize)]
94	#[serde(rename_all = "SCREAMING_SNAKE_CASE", tag = "code")]
95	pub enum OAuthError {
96	    #[error("DPoP keypair generation failed")]
97	    DpopKeyGenFailed,
98	    #[error("DPoP keypair is invalid")]
99	    DpopKeyInvalid,
100	    #[error("DPoP proof construction failed")]
101	    DpopProofFailed,
102	    #[error("Keychain error")]
103	    KeychainError,
104	    #[error("State mismatch in OAuth callback")]
105	    StateMismatch,
106	    #[error("OAuth callback abandoned")]
107	    CallbackAbandoned,
108	    #[error("PAR request failed")]
109	    ParFailed,
110	    #[error("Token exchange failed")]
111	    TokenExchangeFailed,
112	    #[error("Token refresh failed")]
113	    TokenRefreshFailed,
114	    #[error("Refresh token has been revoked or is invalid")]
115	    InvalidGrant,
116	    #[error("Not authenticated")]
117	    NotAuthenticated,
118	}
