120	// ── DPoP keypair ─────────────────────────────────────────────────────────────
121	
122	/// A P-256 keypair used to produce DPoP proofs.
123	///
124	/// The private key scalar (32 bytes) is persisted in the iOS Keychain under
125	/// `"oauth-dpop-key-priv"`. The same key is used for all DPoP proofs across
126	/// app sessions — it is never rotated by this implementation.
127	pub struct DPoPKeypair {
128	    signing_key: SigningKey,
129	}
130	
131	impl DPoPKeypair {
132	    /// Load the DPoP keypair from Keychain, or generate and persist a new one.
133	    pub fn get_or_create() -> Result<Self, OAuthError> {
134	        if let Some(private_bytes) = crate::keychain::load_dpop_key() {
135	            // private_bytes is Zeroizing<[u8; 32]>, which derefs to [u8; 32].
136	            // Dereference to get &[u8; 32], which coerces to &[u8] for from_slice.
137	            let signing_key =
138	                SigningKey::from_slice(&*private_bytes).map_err(|_| OAuthError::DpopKeyInvalid)?;
139	            return Ok(Self { signing_key });
140	        }
141	
142	        // Generate a new P-256 keypair via the shared crypto crate.
143	        let keypair = crypto::generate_p256_keypair().map_err(|_| OAuthError::DpopKeyGenFailed)?;
144	        // `private_key_bytes` is `Zeroizing<[u8; 32]>`, which derefs directly to `[u8; 32]`.
145	        let private_bytes: [u8; 32] = *keypair.private_key_bytes;
146	
147	        crate::keychain::store_dpop_key(&private_bytes).map_err(|_| OAuthError::KeychainError)?;
148	
149	        let signing_key =
150	            SigningKey::from_slice(&private_bytes).map_err(|_| OAuthError::DpopKeyInvalid)?;
151	        Ok(Self { signing_key })
152	    }
153	
154	    /// Build the public JWK for this keypair (EC, P-256, kty/crv/x/y only — no private fields).
155	    ///
156	    /// The relay's validator expects exactly: `{"kty":"EC","crv":"P-256","x":"<b64url>","y":"<b64url>"}`.
157	    pub fn public_jwk(&self) -> serde_json::Value {
158	        let verifying_key = self.signing_key.verifying_key();
159	        let point = verifying_key.to_encoded_point(false); // false = uncompressed: 04 || x || y
160	        let x = URL_SAFE_NO_PAD.encode(point.x().expect("P-256 uncompressed point has x"));
161	        let y = URL_SAFE_NO_PAD.encode(point.y().expect("P-256 uncompressed point has y"));
162	        serde_json::json!({
163	            "kty": "EC",
164	            "crv": "P-256",
165	            "x": x,
166	            "y": y,
167	        })
168	    }
169	
170	    /// Compute the RFC 7638 JWK thumbprint: `base64url(SHA-256(canonical_jwk_json))`.
171	    ///
172	    /// The canonical JSON uses lexicographically-sorted keys (crv, kty, x, y) per RFC 7638 §3.2.
173	    /// This matches the relay's `jwk_thumbprint()` function in `crates/relay/src/auth/dpop.rs`.
174	    pub fn public_jwk_thumbprint(&self) -> String {
175	        let jwk = self.public_jwk();
176	        // Canonical member set per RFC 7638 §3.2 — lexicographic order for EC keys.
177	        // serde_json internally represents JSON objects as BTreeMap, which serializes
178	        // keys in lexicographic order. This is what RFC 7638 §3.2 requires for the
179	        // canonical JSON. The key ordering here (crv < kty < x < y) is lexicographic.
180	        let canonical = serde_json::json!({
181	            "crv": jwk["crv"],
182	            "kty": jwk["kty"],
183	            "x": jwk["x"],
184	            "y": jwk["y"],
185	        });
186	        let canonical_json = serde_json::to_string(&canonical)
187	            .expect("canonical JWK serialization is infallible for known types");
188	        let hash = Sha256::digest(canonical_json.as_bytes());
189	        URL_SAFE_NO_PAD.encode(hash)
190	    }
191	
192	    /// Build a DPoP proof JWT for the given HTTP method, URL, and optional claims.
193	    ///
194	    /// - `htm`: HTTP method in uppercase, e.g. `"POST"` or `"GET"`
195	    /// - `htu`: Full target URL without query string, e.g. `"https://relay.ezpds.com/oauth/token"`
196	    /// - `nonce`: Server-issued nonce from a prior `use_dpop_nonce` 400 response (if any)
197	    /// - `ath`: `base64url(SHA-256(access_token_ascii))` — required for resource requests; None for token requests
198	    ///
199	    /// Proof format: `base64url(header_json)`.`base64url(claims_json)`.`base64url(sig)`
200	    /// where sig is the raw 64-byte R||S P-256 ECDSA signature of the signing input.
201	    pub fn make_proof(
202	        &self,
203	        htm: &str,
204	        htu: &str,
205	        nonce: Option<&str>,
206	        ath: Option<&str>,
207	    ) -> Result<String, OAuthError> {
208	        let jwk = self.public_jwk();
209	
210	        // Header JSON.
211	        let header = serde_json::json!({
212	            "typ": "dpop+jwt",
213	            "alg": "ES256",
214	            "jwk": jwk,
215	        });
216	        let header_b64 = URL_SAFE_NO_PAD
217	            .encode(serde_json::to_vec(&header).map_err(|_| OAuthError::DpopProofFailed)?);
218	
219	        // Claims JSON.
220	        let iat = SystemTime::now()
221	            .duration_since(UNIX_EPOCH)
222	            .map_err(|_| OAuthError::DpopProofFailed)?
223	            .as_secs() as i64;
224	
225	        let mut claims = serde_json::json!({
226	            "jti": Uuid::new_v4().to_string(),
227	            "htm": htm,
228	            "htu": htu,
229	            "iat": iat,
230	        });
231	
232	        if let Some(n) = nonce {
233	            claims["nonce"] = serde_json::Value::String(n.to_string());
234	        }
235	        if let Some(a) = ath {
236	            claims["ath"] = serde_json::Value::String(a.to_string());
237	        }
238	
239	        let claims_b64 = URL_SAFE_NO_PAD
240	            .encode(serde_json::to_vec(&claims).map_err(|_| OAuthError::DpopProofFailed)?);
241	
242	        // Sign `header_b64.claims_b64` bytes with P-256/SHA-256.
243	        let signing_input = format!("{header_b64}.{claims_b64}");
244	        let signature: Signature = self.signing_key.sign(signing_input.as_bytes());
245	        // Normalize to low-S (consistent with the rest of the codebase, even though
246	        // the relay's DPoP validator does not require it — low-S is harmless and keeps
247	        // key usage consistent with ATProto expectations).
248	        let signature = signature.normalize_s().unwrap_or(signature);
249	        let sig_b64 = URL_SAFE_NO_PAD.encode(signature.to_bytes().as_slice());
250	
251	        Ok(format!("{signing_input}.{sig_b64}"))
252	    }
253	
254	    /// Compute `base64url(SHA-256(access_token))` — the `ath` claim for resource requests.
255	    pub fn compute_ath(access_token: &str) -> String {
256	        let hash = Sha256::digest(access_token.as_bytes());
257	        URL_SAFE_NO_PAD.encode(hash)
258	    }
259	}
