261	// ── PKCE utilities ────────────────────────────────────────────────────────────
262	
263	pub mod pkce {
264	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
265	    use rand_core::{OsRng, RngCore};
266	    use sha2::{Digest, Sha256};
267	
268	    /// Generate a PKCE code_verifier and code_challenge pair.
269	    ///
270	    /// - `verifier`: 32 OS-random bytes base64url-encoded (43 chars, all unreserved per RFC 7636 §4.1)
271	    /// - `challenge`: `base64url(SHA-256(verifier))` (S256 method per RFC 7636 §4.2)
272	    ///
273	    /// Returns `(verifier, challenge)`.
274	    pub fn generate() -> (String, String) {
275	        let mut bytes = [0u8; 32];
276	        OsRng.fill_bytes(&mut bytes);
277	        let verifier = URL_SAFE_NO_PAD.encode(bytes);
278	        let challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(verifier.as_bytes()));
279	        (verifier, challenge)
280	    }
281	}
282	
283	/// Generate a CSRF state parameter: 16 OS-random bytes base64url-encoded (22 chars).
284	pub fn generate_state_param() -> String {
285	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
286	    let mut bytes = [0u8; 16];
287	    OsRng.fill_bytes(&mut bytes);
288	    URL_SAFE_NO_PAD.encode(bytes)
289	}
