329	// ── Deep-link handler ─────────────────────────────────────────────────────────
330	
331	/// Process URLs received from the deep-link plugin's `on_open_url` event.
332	///
333	/// Filters for the OAuth callback path, extracts `code` and `state`, validates the
334	/// CSRF state against the pending flow, and sends `CallbackParams` on the oneshot channel.
335	///
336	/// Called from the `on_open_url` closure in lib.rs (sync context — no async).
337	/// A second callback (replay) is silently ignored because `pending_auth.take()` clears
338	/// the slot on first receipt.
339	pub fn handle_deep_link(urls: Vec<url::Url>, app_state: &AppState) {
340	    for url in &urls {
341	        let scheme = url.scheme();
342	        let path = url.path();
343	
344	        if scheme == "dev.malpercio.identitywallet" && path == "/oauth/callback" {
345	            tracing::info!(url = %url, "OAuth deep-link callback received");
346	
347	            // Take the pending flow — clears the slot so replays are silently ignored.
348	            let pending = app_state.pending_auth.lock().unwrap().take();
349	            let Some(flow) = pending else {
350	                tracing::warn!(
351	                    "OAuth callback received but no flow is pending; ignoring (replay?)"
352	                );
353	                return;
354	            };
355	
356	            // Extract code and state from query parameters.
357	            let mut code_opt: Option<String> = None;
358	            let mut state_opt: Option<String> = None;
359	            for (key, value) in url.query_pairs() {
360	                match key.as_ref() {
361	                    "code" => code_opt = Some(value.into_owned()),
362	                    "state" => state_opt = Some(value.into_owned()),
363	                    _ => {}
364	                }
365	            }
366	
367	            let (Some(code), Some(callback_state)) = (code_opt, state_opt) else {
368	                tracing::error!("OAuth callback URL missing code or state parameters");
369	                // Send an explicit error instead of silently dropping the sender.
370	                let _ = flow.tx.send(Err(OAuthError::CallbackAbandoned));
371	                return;
372	            };
373	
374	            // Validate CSRF state — must match before sending on the channel.
375	            if callback_state != flow.csrf_state {
376	                tracing::error!(
377	                    expected = %flow.csrf_state,
378	                    received = %callback_state,
379	                    "CSRF state mismatch in OAuth callback; aborting flow"
380	                );
381	                // Send the error explicitly so start_oauth_flow returns StateMismatch,
382	                // not CallbackAbandoned (which would occur if we just dropped tx).
383	                let _ = flow.tx.send(Err(OAuthError::StateMismatch));
384	                return;
385	            }
386	
387	            let _ = flow.tx.send(Ok(CallbackParams {
388	                code,
389	                state: callback_state,
390	            }));
391	            return;
392	        }
393	
394	        tracing::debug!(url = %url, "ignoring non-OAuth deep-link");
395	    }
396	}
