398	// ── Tauri command ─────────────────────────────────────────────────────────────
399	
400	/// Drive the full OAuth 2.0 PKCE + DPoP authorization round-trip.
401	///
402	/// Called from the SvelteKit frontend via `invoke('start_oauth_flow')`.
403	/// Parks on a Tokio oneshot channel until `handle_deep_link` delivers
404	/// the authorization code from the system browser redirect.
405	///
406	/// # Flow
407	/// 1. Generate PKCE verifier/challenge and CSRF state parameter
408	/// 2. Get-or-create DPoP keypair; build PAR DPoP proof
409	/// 3. POST /oauth/par → receive request_uri
410	/// 4. Open system browser to /oauth/authorize?client_id=...&request_uri=...
411	/// 5. Park on oneshot receiver; handle_deep_link will send the code+state
412	/// 6. Validate CSRF state matches
413	/// 7. POST /oauth/token (authorization_code grant + PKCE verifier + DPoP proof)
414	///    → on use_dpop_nonce 400: retry with server-issued nonce
415	/// 8. Store access_token + refresh_token in Keychain
416	/// 9. Populate AppState.oauth_session
417	#[tauri::command]
418	pub async fn start_oauth_flow(
419	    app: tauri::AppHandle,
420	    state: tauri::State<'_, AppState>,
421	    login_hint: Option<String>,
422	) -> Result<(), OAuthError> {
423	    // OpenerExt adds the `.opener()` method to AppHandle.
424	    use tauri_plugin_opener::OpenerExt;
425	
426	    let relay = state.relay_client();
427	
428	    // 1. Generate PKCE and CSRF state.
429	    let (pkce_verifier, pkce_challenge) = pkce::generate();
430	    let csrf_state = generate_state_param();
431	
432	    // 2. Get-or-create DPoP keypair.
433	    let dpop = DPoPKeypair::get_or_create()?;
434	    let dpop_jkt = dpop.public_jwk_thumbprint();
435	
436	    let par_htu = format!("{}/oauth/par", state.relay_client().base_url_str());
437	    let par_proof = dpop.make_proof("POST", &par_htu, None, None)?;
438	
439	    // 3. PAR call.
440	    let par_resp = relay
441	        .par(
442	            &pkce_challenge,
443	            &csrf_state,
444	            &par_proof,
445	            &dpop_jkt,
446	            login_hint.as_deref(),
447	        )
448	        .await?;
449	
450	    // 4. Set up the oneshot channel and park pending_auth.
451	    let (tx, rx) = tokio::sync::oneshot::channel::<Result<CallbackParams, OAuthError>>();
452	    {
453	        let mut pending = state.pending_auth.lock().unwrap();
454	        *pending = Some(PendingOAuthFlow {
455	            tx,
456	            pkce_verifier: pkce_verifier.clone(),
457	            csrf_state: csrf_state.clone(),
458	        });
459	    } // Mutex guard dropped here — not held across .await.
460	
461	    // 5. Open Safari to the authorization endpoint.
462	    let auth_url = {
463	        let base = state.relay_client().base_url_str();
464	        let request_uri_encoded =
465	            url::form_urlencoded::byte_serialize(par_resp.request_uri.as_bytes())
466	                .collect::<String>();
467	        let mut u = format!(
468	            "{base}/oauth/authorize?client_id=dev.malpercio.identitywallet&request_uri={request_uri_encoded}"
469	        );
470	        if let Some(hint) = &login_hint {
471	            let hint_encoded =
472	                url::form_urlencoded::byte_serialize(hint.as_bytes()).collect::<String>();
473	            u.push_str(&format!("&login_hint={hint_encoded}"));
474	        }
475	        u
476	    };
477	
478	    app.opener()
479	        .open_url(&auth_url, None::<&str>)
480	        .map_err(|e| {
481	            tracing::error!(error = %e, "failed to open system browser for OAuth");
482	            OAuthError::ParFailed
483	        })?;
484	
485	    // 6. Wait for the deep-link callback to deliver the authorization code.
486	    // The outer ? handles RecvError (channel dropped) → CallbackAbandoned.
487	    // The inner ? propagates OAuthError::StateMismatch if handle_deep_link detected a CSRF mismatch.
488	    let callback = rx.await.map_err(|_| OAuthError::CallbackAbandoned)??;
489	
490	    // 7. Token exchange.
491	    let token_htu = format!("{}/oauth/token", state.relay_client().base_url_str());
492	    let (token_resp, initial_nonce) =
493	        exchange_code_with_retry(relay, &dpop, &callback.code, &pkce_verifier, &token_htu).await?;
494	
495	    // 8. Store tokens in Keychain.
496	    crate::keychain::store_oauth_tokens(&token_resp.access_token, &token_resp.refresh_token)
497	        .map_err(|_| OAuthError::KeychainError)?;
498	
499	    // 9. Update AppState.
500	    // Seed dpop_nonce from the token response to avoid a guaranteed use_dpop_nonce retry
501	    // on the first OAuthClient request immediately after login.
502	    let expires_at = std::time::SystemTime::now()
503	        .duration_since(std::time::UNIX_EPOCH)
504	        .map_err(|_| OAuthError::TokenExchangeFailed)?
505	        .as_secs()
506	        + token_resp.expires_in;
507	
508	    let mut session = state.oauth_session.lock().unwrap();
509	    *session = Some(OAuthSession {
510	        access_token: token_resp.access_token,
511	        refresh_token: token_resp.refresh_token,
512	        expires_at,
513	        dpop_nonce: initial_nonce,
514	    });
515	
516	    tracing::info!("OAuth flow complete; session stored");
517	    Ok(())
518	}
