520	/// Perform the authorization code token exchange with one retry on `use_dpop_nonce`.
521	///
522	/// Returns the token response and the `DPoP-Nonce` header value from the successful
523	/// response (if present). Storing this nonce in the session avoids a guaranteed
524	/// `use_dpop_nonce` retry on the very first `OAuthClient` request after login.
525	///
526	/// The relay always requires a DPoP nonce at the token endpoint (RFC 9449 §8).
527	/// On the first attempt, the nonce is absent; the relay returns 400 with `use_dpop_nonce`
528	/// and a `DPoP-Nonce` response header. We retry exactly once with that nonce.
529	async fn exchange_code_with_retry(
530	    relay: &crate::http::RelayClient,
531	    dpop: &DPoPKeypair,
532	    code: &str,
533	    pkce_verifier: &str,
534	    token_htu: &str,
535	) -> Result<(crate::http::TokenResponse, Option<String>), OAuthError> {
536	    let proof = dpop.make_proof("POST", token_htu, None, None)?;
537	    let resp = relay.token_exchange(code, pkce_verifier, &proof).await?;
538	
539	    if resp.status().as_u16() == 200 {
540	        // Capture DPoP-Nonce before consuming the body.
541	        let nonce = resp
542	            .headers()
543	            .get("DPoP-Nonce")
544	            .and_then(|v| v.to_str().ok())
545	            .map(str::to_string);
546	        let token = resp
547	            .json::<crate::http::TokenResponse>()
548	            .await
549	            .map_err(|e| {
550	                tracing::error!(error = %e, "token response deserialization failed");
551	                OAuthError::TokenExchangeFailed
552	            })?;
553	        return Ok((token, nonce));
554	    }
555	
556	    // Check for use_dpop_nonce — extract the nonce from the DPoP-Nonce header.
557	    let nonce = resp
558	        .headers()
559	        .get("DPoP-Nonce")
560	        .and_then(|v| v.to_str().ok())
561	        .map(str::to_string);
562	
563	    let error_body = resp
564	        .json::<crate::http::TokenErrorResponse>()
565	        .await
566	        .unwrap_or_else(|_| crate::http::TokenErrorResponse {
567	            error: "unknown".into(),
568	            error_description: None,
569	        });
570	
571	    if error_body.error == "use_dpop_nonce" {
572	        if let Some(nonce_val) = nonce {
573	            tracing::debug!(nonce = %nonce_val, "retrying token exchange with server nonce");
574	            let proof_with_nonce = dpop.make_proof("POST", token_htu, Some(&nonce_val), None)?;
575	            let retry_resp = relay
576	                .token_exchange(code, pkce_verifier, &proof_with_nonce)
577	                .await?;
578	            if retry_resp.status().as_u16() == 200 {
579	                // Capture DPoP-Nonce from the retry response too.
580	                let retry_nonce = retry_resp
581	                    .headers()
582	                    .get("DPoP-Nonce")
583	                    .and_then(|v| v.to_str().ok())
584	                    .map(str::to_string);
585	                let token = retry_resp
586	                    .json::<crate::http::TokenResponse>()
587	                    .await
588	                    .map_err(|e| {
589	                        tracing::error!(error = %e, "retry token response deserialization failed");
590	                        OAuthError::TokenExchangeFailed
591	                    })?;
592	                return Ok((token, retry_nonce));
593	            }
594	            tracing::error!("token exchange failed after nonce retry");
595	            return Err(OAuthError::TokenExchangeFailed);
596	        }
597	    }
598	
599	    tracing::error!(error = %error_body.error, "token exchange failed");
600	    Err(OAuthError::TokenExchangeFailed)
601	}
