721	    #[test]
722	    fn dpop_proof_signature_verifies_against_embedded_jwk() {
723	        use p256::elliptic_curve::sec1::EncodedPoint;
724	
725	        let kp = DPoPKeypair::get_or_create().expect("keypair must generate");
726	        let proof = kp
727	            .make_proof("POST", "https://example.com/oauth/token", None, None)
728	            .expect("proof must build");
729	        let (header_b64, claims_b64, sig_b64) = split_proof(&proof);
730	
731	        // Reconstruct verifying key from the embedded JWK.
732	        let header = decode_jwt_part(header_b64);
733	        let x_bytes = URL_SAFE_NO_PAD
734	            .decode(header["jwk"]["x"].as_str().unwrap())
735	            .unwrap();
736	        let y_bytes = URL_SAFE_NO_PAD
737	            .decode(header["jwk"]["y"].as_str().unwrap())
738	            .unwrap();
739	        // Build uncompressed point: 0x04 || x || y
740	        let mut point_bytes = vec![0x04u8];
741	        point_bytes.extend_from_slice(&x_bytes);
742	        point_bytes.extend_from_slice(&y_bytes);
743	        let point = EncodedPoint::<p256::NistP256>::from_bytes(&point_bytes)
744	            .expect("valid uncompressed point");
745	        let verifying_key = p256::ecdsa::VerifyingKey::from_encoded_point(&point)
746	            .expect("valid verifying key from JWK");
747	
748	        // Decode the signature.
749	        let sig_bytes = URL_SAFE_NO_PAD
750	            .decode(sig_b64)
751	            .expect("valid base64url sig");
752	        let signature = p256::ecdsa::Signature::from_bytes(sig_bytes.as_slice().into())
753	            .expect("valid R||S signature bytes");
754	
755	        // Verify the signature over the signing input.
756	        let signing_input = format!("{header_b64}.{claims_b64}");
757	        verifying_key
758	            .verify(signing_input.as_bytes(), &signature)
759	            .expect("signature must verify against embedded JWK");
760	    }
