56	/// Load home screen data: relay health, session info, and Keychain share status.
57	///
58	/// Fires GET /xrpc/_health and GET /xrpc/com.atproto.server.getSession
59	/// concurrently via tokio::join!. Always succeeds — partial failures are
60	/// encoded in HomeData fields rather than returned as Err.
61	#[tauri::command]
62	pub async fn load_home_data(state: tauri::State<'_, AppState>) -> Result<HomeData, String> {
63	    let share1_in_keychain = crate::keychain::get_item("recovery-share-1").is_ok();
64	
65	    // Clone session out of AppState (drops the lock immediately).
66	    let session_opt = {
67	        let guard = state.oauth_session.lock().unwrap();
68	        guard.clone()
69	    };
70	
71	    let Some(session) = session_opt else {
72	        let relay_healthy = ping_relay_health(state.relay_client()).await;
73	        return Ok(HomeData {
74	            relay_healthy,
75	            session: None,
76	            session_error: Some("NOT_AUTHENTICATED".to_string()),
77	            share1_in_keychain,
78	        });
79	    };
80	
81	    let session_arc = Arc::new(Mutex::new(session));
82	
83	    let oauth_client = match crate::oauth_client::OAuthClient::new(
84	        session_arc.clone(),
85	        state.relay_client().base_url_str().to_owned(),
86	    ) {
87	        Ok(c) => c,
88	        Err(e) => {
89	            tracing::error!(error = %e, "OAuthClient construction failed");
90	            return Ok(HomeData {
91	                relay_healthy: ping_relay_health(state.relay_client()).await,
92	                session: None,
93	                session_error: Some(oauth_error_code(&e)),
94	                share1_in_keychain,
95	            });
96	        }
97	    };
98	
99	    let (relay_healthy, session_result) = tokio::join!(
100	        ping_relay_health(state.relay_client()),
101	        oauth_client.get("/xrpc/com.atproto.server.getSession"),
102	    );
103	
104	    let (session_info, session_error) = match session_result {
105	        Ok(resp) if resp.status().is_success() => {
106	            match resp.json::<GetSessionResponse>().await {
107	                Ok(gs) => {
108	                    // Write back potentially-refreshed tokens to AppState.
109	                    let refreshed = session_arc.lock().unwrap().clone();
110	                    *state.oauth_session.lock().unwrap() = Some(refreshed);
111	                    (
112	                        Some(SessionInfo {
113	                            did: gs.did,
114	                            handle: gs.handle,
115	                            email: gs.email,
116	                            email_confirmed: gs.email_confirmed,
117	                            did_doc: gs.did_doc,
118	                        }),
119	                        None,
120	                    )
121	                }
122	                Err(e) => {
123	                    tracing::error!(error = %e, "getSession deserialization failed");
124	                    (None, Some("SESSION_PARSE_ERROR".to_string()))
125	                }
126	            }
127	        }
128	        Ok(resp) => {
129	            tracing::warn!(status = %resp.status(), "getSession returned non-success");
130	            (None, Some("NOT_AUTHENTICATED".to_string()))
131	        }
132	        Err(e) => {
133	            tracing::error!(error = %e, "getSession request failed");
134	            (None, Some(oauth_error_code(&e)))
135	        }
136	    };
137	
138	    Ok(HomeData {
139	        relay_healthy,
140	        session: session_info,
141	        session_error,
142	        share1_in_keychain,
143	    })
144	}
