146	/// Clear OAuth tokens and DID from Keychain and wipe the in-memory session.
147	///
148	/// Always succeeds — Keychain delete errors are swallowed so the frontend
149	/// unconditionally navigates to the welcome screen.
150	#[tauri::command]
151	pub async fn log_out(state: tauri::State<'_, AppState>) -> Result<(), String> {
152	    for key in &["oauth-access-token", "oauth-refresh-token", "did"] {
153	        if let Err(e) = crate::keychain::delete_item(key) {
154	            if !crate::keychain::is_not_found(&e) {
155	                tracing::warn!(error = %e, key = key, "Keychain delete failed during logout");
156	            }
157	        }
158	    }
159	    *state.oauth_session.lock().unwrap() = None;
160	    Ok(())
161	}
