165	/// Ping the relay health endpoint. Named to avoid ambiguity with any future
166	/// public IPC commands.
167	async fn ping_relay_health(relay_client: &crate::http::RelayClient) -> bool {
168	    relay_client
169	        .get("/xrpc/_health")
170	        .await
171	        .map(|r| r.status().is_success())
172	        .unwrap_or(false)
173	}
174	
175	fn oauth_error_code(e: &OAuthError) -> String {
176	    serde_json::to_value(e)
177	        .ok()
178	        .and_then(|v| v["code"].as_str().map(String::from))
179	        .unwrap_or_else(|| {
180	            tracing::warn!("OAuthError could not be serialized to a code string");
181	            "UNKNOWN".to_string()
182	        })
183	}
