247	/// Map a relay 409 error subcode string to a typed `CreateAccountError` variant.
248	fn map_409_subcode(code: &str) -> CreateAccountError {
249	    match code {
250	        "CLAIM_CODE_REDEEMED" => CreateAccountError::RedeemedCode,
251	        "ACCOUNT_EXISTS" => CreateAccountError::EmailTaken,
252	        "HANDLE_TAKEN" => CreateAccountError::HandleTaken,
253	        other => CreateAccountError::Unknown {
254	            message: format!("409: {other}"),
255	        },
256	    }
257	}
258	
259	/// Validate a relay URL: must parse as http or https with a non-empty host.
260	/// Strips any trailing slash and returns the normalized URL string.
261	fn normalize_relay_url(url: &str) -> Result<String, RelayConfigError> {
262	    let parsed = url::Url::parse(url).map_err(|_| RelayConfigError::InvalidUrl)?;
263	    match parsed.scheme() {
264	        "http" | "https" => {}
265	        _ => return Err(RelayConfigError::InvalidUrl),
266	    }
267	    if parsed.host().is_none() {
268	        return Err(RelayConfigError::InvalidUrl);
269	    }
270	    let path = parsed.path();
271	    if !path.is_empty() && path != "/" {
272	        return Err(RelayConfigError::InvalidUrl);
273	    }
274	    Ok(url.trim_end_matches('/').to_string())
275	}
