279	#[tauri::command]
280	async fn create_account(
281	    claim_code: String,
282	    email: String,
283	    handle: String,
284	    state: tauri::State<'_, oauth::AppState>,
285	) -> Result<CreateAccountResult, CreateAccountError> {
286	    // 1. Get or create the device's SE-backed (or simulator-fallback) P-256 key.
287	    let device_key = device_key::get_or_create().map_err(|e| {
288	        tracing::warn!(error = %e, "device key creation failed during account creation");
289	        CreateAccountError::KeychainError
290	    })?;
291	
292	    // 2. POST to relay.
293	    let req = CreateMobileAccountRequest {
294	        email,
295	        handle,
296	        device_public_key: device_key.multibase,
297	        platform: "ios".to_string(),
298	        claim_code,
299	    };
300	
301	    let resp = state
302	        .relay_client()
303	        .post("/v1/accounts/mobile", &req)
304	        .await
305	        .map_err(|e| CreateAccountError::NetworkError {
306	            message: e.to_string(),
307	        })?;
308	
309	    let status = resp.status();
310	
311	    if status.is_success() {
312	        // 3. Deserialize success body.
313	        let body: CreateMobileAccountResponse =
314	            resp.json().await.map_err(|e| CreateAccountError::Unknown {
315	                message: e.to_string(),
316	            })?;
317	
318	        // 4. Store tokens in Keychain.
319	        // If session-token write fails, best-effort remove the already-written device-token.
320	        // The device key is persistent by design and is NOT cleaned up on failure.
321	        keychain::store_item("device-token", body.device_token.as_bytes()).map_err(|_| {
322	            // device-token write failed — nothing to clean up; the device key is persistent by design.
323	            CreateAccountError::KeychainError
324	        })?;
325	
326	        keychain::store_item("session-token", body.session_token.as_bytes()).map_err(|_| {
327	            // Best-effort cleanup: remove the already-written device-token.
328	            let _ = keychain::delete_item("device-token");
329	            CreateAccountError::KeychainError
330	        })?;
331	
332	        Ok(CreateAccountResult {
333	            next_step: body.next_step,
334	        })
335	    } else {
336	        // 5. Map relay error codes to typed variants.
337	        match status.as_u16() {
338	            // 404: Relay returns this for both invalid (never-existed) and expired claim codes.
339	            // The frontend cannot distinguish them, so we map both to ExpiredCode.
340	            404 => Err(CreateAccountError::ExpiredCode),
341	            409 => {
342	                let envelope: RelayErrorEnvelope =
343	                    resp.json().await.map_err(|e| CreateAccountError::Unknown {
344	                        message: e.to_string(),
345	                    })?;
346	                Err(map_409_subcode(&envelope.error.code))
347	            }
348	            _ => Err(CreateAccountError::NetworkError {
349	                message: format!("HTTP {}", status.as_u16()),
350	            }),
351	        }
352	    }
353	}
