366	#[tauri::command]
367	async fn perform_did_ceremony(
368	    handle: String,
369	    password: String,
370	    state: tauri::State<'_, oauth::AppState>,
371	) -> Result<DIDCeremonyResult, DIDCeremonyError> {
372	    // Step 1: Get or create the device's P-256 key (serves as rotation key).
373	    let device_key = device_key::get_or_create().map_err(|e| {
374	        tracing::warn!(error = %e, "device key creation failed during DID ceremony");
375	        DIDCeremonyError::KeyNotFound
376	    })?;
377	
378	    // Step 2: Retrieve the pending session token — needed to authenticate the
379	    // per-account signing-key request below and the DID promotion later.
380	    let pending_token = {
381	        let token_bytes = keychain::get_item("session-token").map_err(|e| {
382	            tracing::warn!(error = %e, "failed to retrieve session-token from keychain");
383	            DIDCeremonyError::KeychainError
384	        })?;
385	        String::from_utf8(token_bytes).map_err(|e| {
386	            tracing::warn!(error = %e, "session-token bytes are not valid UTF-8");
387	            DIDCeremonyError::KeychainError
388	        })?
389	    };
390	
391	    // Step 3: Fetch this account's per-account repo signing key (pending-session auth).
392	    // The relay issues it idempotently; we publish it as the DID's #atproto verification
393	    // method, and the relay signs the repo's commits with the matching private key.
394	    let resp = state
395	        .relay_client()
396	        .get_with_bearer("/v1/repo-signing-key", &pending_token)
397	        .await
398	        .map_err(|e| DIDCeremonyError::NetworkError {
399	            message: e.to_string(),
400	        })?;
401	
402	    let status = resp.status();
403	    if status.as_u16() == 503 {
404	        return Err(DIDCeremonyError::NoRelaySigningKey);
405	    }
406	    if !status.is_success() {
407	        let body = resp.text().await.unwrap_or_else(|e| {
408	            tracing::warn!(error = %e, "failed to read GET /v1/repo-signing-key error body");
409	            "<body read failed>".to_string()
410	        });
411	        tracing::error!(status = %status, body = %body, "GET /v1/repo-signing-key returned non-success status");
412	        return Err(DIDCeremonyError::RelayKeyFetchFailed);
413	    }
414	
415	    let relay_key: RelaySigningKey = resp.json().await.map_err(|e| {
416	        tracing::error!(error = %e, "failed to deserialize repo signing key response");
417	        DIDCeremonyError::RelayKeyFetchFailed
418	    })?;
419	
420	    // Step 4: Build signed genesis op — device key as rotation key, per-account repo key as signing key.
421	    // On device, the private key never leaves the Secure Enclave; on Simulator and macOS, a software key is used instead.
422	    let rotation_key = DidKeyUri(device_key.key_id.clone());
423	    let signing_key = DidKeyUri(relay_key.key_id.clone());
424	
425	    let genesis_op = build_did_plc_genesis_op_with_external_signer(
426	        &rotation_key,
427	        &signing_key,
428	        &handle,
429	        state.relay_client().base_url_str(),
430	        |data| {
431	            device_key::sign(data)
432	                .map_err(|e| CryptoError::PlcOperation(format!("device signing failed: {e}")))
433	        },
434	    )
435	    .map_err(|e| {
436	        tracing::error!(error = %e, "genesis op signing failed during DID ceremony");
437	        DIDCeremonyError::SigningFailed
438	    })?;
439	
440	    // Step 6: POST the signed genesis op to the relay to promote the account to a full DID.
441	    let create_did_req = CreateDidRequest {
442	        rotation_key_public: device_key.key_id,
443	        signed_creation_op: serde_json::from_str(&genesis_op.signed_op_json).map_err(|e| {
444	            tracing::error!(error = %e, "genesis op JSON is not valid JSON");
445	            DIDCeremonyError::SigningFailed
446	        })?,
447	        password,
448	    };
449	
450	    let resp = state
451	        .relay_client()
452	        .post_with_bearer("/v1/dids", &create_did_req, &pending_token)
453	        .await
454	        .map_err(|e| DIDCeremonyError::NetworkError {
455	            message: e.to_string(),
456	        })?;
457	
458	    if !resp.status().is_success() {
459	        let status = resp.status();
460	        let body = resp.text().await.unwrap_or_else(|e| {
461	            tracing::warn!(error = %e, "failed to read POST /v1/dids error body");
462	            "<body read failed>".to_string()
463	        });
464	        tracing::error!(status = %status, body = %body, "POST /v1/dids returned non-success status");
465	        return Err(DIDCeremonyError::DidCreationFailed);
466	    }
467	
468	    let create_did_resp: CreateDidResponse = resp.json().await.map_err(|e| {
469	        tracing::error!(error = %e, "failed to deserialize POST /v1/dids response");
470	        DIDCeremonyError::DidCreationFailed
471	    })?;
472	
473	    // Step 6: Overwrite session-token with the upgraded full session token.
474	    keychain::store_item("session-token", create_did_resp.session_token.as_bytes()).map_err(
475	        |e| {
476	            tracing::error!(error = %e, "failed to persist upgraded session-token to keychain");
477	            DIDCeremonyError::KeychainError
478	        },
479	    )?;
480	
481	    // Step 7: Persist the DID for use in subsequent app sessions.
482	    keychain::store_item("did", create_did_resp.did.as_bytes()).map_err(|e| {
483	        tracing::error!(error = %e, did = %create_did_resp.did, "failed to persist DID to keychain");
484	        DIDCeremonyError::KeychainError
485	    })?;
486	
487	    // Step 8: Store Share 1 in iCloud Keychain for automatic backup.
488	    // Uses ShareStorageFailed (not KeychainError) because the DID is already committed:
489	    // retrying the ceremony will hit DidAlreadyExists. The frontend can surface a distinct
490	    // message rather than telling the user to retry the whole ceremony.
491	    keychain::store_item(
492	        "recovery-share-1",
493	        create_did_resp.shamir_share_1.as_bytes(),
494	    )
495	    .map_err(|e| {
496	        tracing::error!(error = %e, "DID committed but recovery share 1 keychain write failed");
497	        DIDCeremonyError::ShareStorageFailed
498	    })?;
499	
500	    Ok(DIDCeremonyResult {
501	        did: create_did_resp.did,
502	        share3: create_did_resp.shamir_share_3,
503	    })
504	}
