506	/// Register the user's handle with the relay and set up HTTP resolution.
507	///
508	/// Fetches the relay's primary user domain via `GET /xrpc/com.atproto.server.describeServer`,
509	/// constructs the full handle (`{handle_label}.{domain}`), reads the DID and session token
510	/// from Keychain, then POSTs to `POST /v1/handles`.
511	///
512	/// Returns the full handle and DNS propagation status on success.
513	#[tauri::command]
514	async fn register_handle(
515	    handle_label: String,
516	    state: tauri::State<'_, oauth::AppState>,
517	) -> Result<RegisterHandleResult, RegisterHandleError> {
518	    // Step 1: Fetch the relay's primary user domain.
519	    let resp = state
520	        .relay_client()
521	        .get("/xrpc/com.atproto.server.describeServer")
522	        .await
523	        .map_err(|e| RegisterHandleError::NetworkError {
524	            message: e.to_string(),
525	        })?;
526	
527	    if !resp.status().is_success() {
528	        return Err(RegisterHandleError::NetworkError {
529	            message: format!("describeServer returned HTTP {}", resp.status().as_u16()),
530	        });
531	    }
532	
533	    let server_info: DescribeServerResponse =
534	        resp.json()
535	            .await
536	            .map_err(|e| RegisterHandleError::Unknown {
537	                message: format!("failed to parse describeServer response: {e}"),
538	            })?;
539	
540	    let domain = server_info
541	        .available_user_domains
542	        .into_iter()
543	        .next()
544	        .ok_or(RegisterHandleError::NoDomains)?;
545	
546	    let full_handle = format!("{handle_label}.{domain}");
547	
548	    // Step 2: Read DID and session token from Keychain.
549	    // Missing DID here is a post-ceremony invariant violation — error! is appropriate.
550	    let did_bytes = keychain::get_item("did").map_err(|e| {
551	        tracing::error!(error = %e, "DID not found in Keychain during handle registration — ceremony invariant violated");
552	        RegisterHandleError::KeychainError
553	    })?;
554	    let did = String::from_utf8(did_bytes).map_err(|e| {
555	        tracing::error!(error = %e, "DID bytes are not valid UTF-8");
556	        RegisterHandleError::KeychainError
557	    })?;
558	
559	    let token_bytes = keychain::get_item("session-token").map_err(|e| {
560	        tracing::warn!(error = %e, "failed to read session-token from Keychain during handle registration");
561	        RegisterHandleError::KeychainError
562	    })?;
563	    let session_token = String::from_utf8(token_bytes).map_err(|e| {
564	        tracing::warn!(error = %e, "session-token bytes are not valid UTF-8");
565	        RegisterHandleError::KeychainError
566	    })?;
567	
568	    // Step 3: POST to /v1/handles.
569	    let req = CreateHandleRequest {
570	        account_id: did,
571	        handle: full_handle.clone(),
572	    };
573	
574	    let resp = state
575	        .relay_client()
576	        .post_with_bearer("/v1/handles", &req, &session_token)
577	        .await
578	        .map_err(|e| RegisterHandleError::NetworkError {
579	            message: e.to_string(),
580	        })?;
581	
582	    let status = resp.status();
583	
584	    if status.is_success() {
585	        let body: CreateHandleRelayResponse =
586	            resp.json()
587	                .await
588	                .map_err(|e| RegisterHandleError::Unknown {
589	                    message: format!("failed to parse /v1/handles response: {e}"),
590	                })?;
591	        Ok(RegisterHandleResult {
592	            handle: full_handle,
593	            dns_status: body.dns_status,
594	        })
595	    } else {
596	        match status.as_u16() {
597	            400 => {
598	                let envelope: RelayErrorEnvelope =
599	                    resp.json()
600	                        .await
601	                        .map_err(|e| RegisterHandleError::Unknown {
602	                            message: e.to_string(),
603	                        })?;
604	                if envelope.error.code == "INVALID_HANDLE" {
605	                    Err(RegisterHandleError::InvalidHandle)
606	                } else {
607	                    Err(RegisterHandleError::Unknown {
608	                        message: format!("400: {}", envelope.error.code),
609	                    })
610	                }
611	            }
612	            // 401 means the relay rejected the session token — it's expired or revoked.
613	            // The Keychain read already succeeded; this is an auth problem, not a Keychain problem.
614	            401 => Err(RegisterHandleError::SessionExpired),
615	            409 => Err(RegisterHandleError::HandleTaken),
616	            502 => Err(RegisterHandleError::DnsError),
617	            other => Err(RegisterHandleError::NetworkError {
618	                message: format!("HTTP {other}"),
619	            }),
620	        }
621	    }
622	}
