633	/// Validate `url`, confirm the relay is reachable, save to Keychain, and
634	/// initialize the runtime relay client.
635	///
636	/// After this call succeeds, all subsequent IPC commands that use the relay
637	/// will use the saved URL for the remainder of the app session and on all
638	/// future launches.
639	#[tauri::command]
640	async fn save_relay_url(
641	    url: String,
642	    state: tauri::State<'_, oauth::AppState>,
643	) -> Result<(), RelayConfigError> {
644	    let normalized = normalize_relay_url(&url)?;
645	    let resp = http::RelayClient::new_with_url(normalized.clone())
646	        .get("/xrpc/_health")
647	        .await
648	        .map_err(|e| {
649	            tracing::warn!(error = %e, url = %normalized, "relay health check failed");
650	            RelayConfigError::Unreachable
651	        })?;
652	    if !resp.status().is_success() {
653	        tracing::warn!(
654	            status = %resp.status(),
655	            url = %normalized,
656	            "relay health check returned non-success status"
657	        );
658	        // Both transport failures (DNS, TLS, timeout) and non-2xx HTTP responses
659	        // map to Unreachable — the frontend only needs to know "can't use this URL".
660	        return Err(RelayConfigError::Unreachable);
661	    }
662	    keychain::store_relay_url(&normalized).map_err(|e| {
663	        tracing::error!(error = %e, "failed to save relay URL to Keychain");
664	        RelayConfigError::KeychainError
665	    })?;
666	    state.set_relay_client(normalized);
667	    Ok(())
668	}
