707	/// Retrieve the device key ID (did:key URI) for a claimed identity.
708	///
709	/// Returns the device key's did:key URI, which can be compared against rotation keys
710	/// in the DID document to determine if the device key is the primary rotation key.
711	///
712	/// The frontend uses this in IdentityListHome to show rotation key status badges.
713	#[tauri::command]
714	fn get_device_key_id(did: String) -> Result<String, identity_store::IdentityStoreError> {
