720	/// Check whether the relay can resolve `handle` to `expected_did` via the ATProto
721	/// `resolveHandle` endpoint.
722	///
723	/// Returns `true` when the relay resolves the handle to the expected DID (HTTP 200 + matching
724	/// `did` field). Returns `false` for any other response (handle not yet propagated, relay
725	/// unreachable, DID mismatch). Returns `Result<bool, String>` for Tauri IPC compatibility, but
726	/// never returns `Err` — callers can safely poll on an interval.
727	#[tauri::command]
728	async fn check_handle_resolution(
729	    handle: String,
730	    expected_did: String,
731	    state: tauri::State<'_, oauth::AppState>,
732	) -> Result<bool, String> {
733	    // ATProto handles are alphanumeric + hyphens + dots — all URL-safe; no percent-encoding needed.
734	    let path = format!("/xrpc/com.atproto.identity.resolveHandle?handle={handle}");
735	
736	    let resp = match state.relay_client().get(&path).await {
737	        Ok(r) => r,
738	        Err(e) => {
739	            tracing::debug!(error = %e, "check_handle_resolution: network error, returning false");
740	            return Ok(false);
741	        }
742	    };
743	
744	    if !resp.status().is_success() {
745	        tracing::debug!(
746	            status = resp.status().as_u16(),
747	            "check_handle_resolution: non-success response, returning false"
748	        );
749	        return Ok(false);
750	    }
751	
752	    match resp.json::<ResolveHandleResponse>().await {
753	        Ok(body) => Ok(body.did == expected_did),
754	        Err(e) => {
755	            tracing::debug!(error = %e, "check_handle_resolution: failed to parse response, returning false");
756	            Ok(false)
757	        }
758	    }
759	}
