761	#[cfg_attr(mobile, tauri::mobile_entry_point)]
762	pub fn run() {
763	    tauri::Builder::default()
764	        .manage(oauth::AppState::new())
765	        .plugin(
766	            tauri_plugin_log::Builder::new()
767	                .level(log::LevelFilter::Debug)
768	                .build(),
769	        )
770	        .plugin(tauri_plugin_deep_link::init())
771	        .plugin(tauri_plugin_opener::init())
772	        .setup(|app| {
773	            // Restore relay URL from Keychain if previously configured.
774	            if let Some(url) = keychain::load_relay_url() {
775	                app.state::<oauth::AppState>().set_relay_client(url);
776	            }
777	
778	            let app_handle = app.app_handle().clone();
779	            app.deep_link().on_open_url(move |event| {
780	                let state = app_handle.state::<oauth::AppState>();
781	                oauth::handle_deep_link(event.urls(), &state);
782	            });
783	
784	            // On relaunch: restore persisted session from Keychain and notify frontend.
785	            // The 300 ms delay lets the SvelteKit app boot and register its event listener
786	            // before the event fires — emitting synchronously here would be dropped.
787	            if let Some((access, refresh)) = keychain::load_oauth_tokens() {
788	                {
789	                    let state = app.state::<oauth::AppState>();
790	                    *state.oauth_session.lock().unwrap() = Some(oauth::OAuthSession {
791	                        access_token: access,
792	                        refresh_token: refresh,
793	                        // expires_at = 0 ensures OAuthClient refreshes immediately on first use.
794	                        expires_at: 0,
795	                        dpop_nonce: None,
796	                    });
797	                }
798	                let handle = app.handle().clone();
799	                tauri::async_runtime::spawn(async move {
800	                    tokio::time::sleep(std::time::Duration::from_millis(300)).await;
801	                    handle.emit("auth_ready", ()).ok();
802	                });
803	            }
804	
805	            // Start PLC monitoring timer (15-minute interval)
806	            let monitor_handle = app.handle().clone();
807	            tauri::async_runtime::spawn(plc_monitor::run_monitoring_loop(monitor_handle));
808	
809	            Ok(())
810	        })
811	        .invoke_handler(tauri::generate_handler![
812	            create_account,
813	            get_or_create_device_key,
814	            sign_with_device_key,
815	            perform_did_ceremony,
816	            register_handle,
817	            check_handle_resolution,
818	            list_identities,
819	            get_stored_did_doc,
820	            get_device_key_id,
821	            get_relay_url,
822	            save_relay_url,
823	            home::load_home_data,
824	            home::log_out,
825	            oauth::start_oauth_flow,
826	            claim::resolve_identity,
827	            claim::start_pds_auth,
828	            claim::request_claim_verification,
829	            claim::sign_and_verify_claim,
830	            claim::submit_claim,
831	            plc_monitor::check_identity_status,
832	            recovery::build_recovery_override_cmd,
833	            recovery::submit_recovery_override_cmd,
834	        ])
835	        .run(tauri::generate_context!())
836	        .expect("error while running tauri application");
837	}
