1	<script lang="ts">
2	  import { onMount, onDestroy } from 'svelte';
3	  import { listen, type UnlistenFn } from '@tauri-apps/api/event';
4	  import { listIdentities, getStoredDidDoc, getDeviceKeyId, checkIdentityStatus, type UnauthorizedChange, type IdentityStatus } from '$lib/ipc';
5	  import { extractPdsFromPlcDoc, extractHandle, truncateDid } from '$lib/did-doc-utils';
6	  import DIDAvatar from './DIDAvatar.svelte';
7	
8	  let {
9	    onadd,
10	    onselect,
11	    onalert,
12	  }: {
13	    onadd: () => void;
14	    onselect: (did: string, didDoc: Record<string, unknown>) => void;
15	    onalert?: (did: string, changes: UnauthorizedChange[]) => void;
16	  } = $props();
17	
18	  interface IdentityCard {
19	    did: string;
20	    handle: string | null;
21	    pdsUrl: string | null;
22	    deviceKeyIsRoot: boolean | null;
23	  }
24	
25	  let identities = $state<IdentityCard[]>([]);
26	  let didDocs = $state<Map<string, Record<string, unknown>>>(new Map());
27	  let loading = $state(true);
28	  let loadError = $state<string | null>(null);
29	  let alertData = $state<Map<string, UnauthorizedChange[]>>(new Map());
30	  let unlisten: UnlistenFn | null = null;
31	
32	  // Total unauthorized changes across all identities, for the monitoring banner.
33	  let alertCount = $derived(
34	    Array.from(alertData.values()).reduce((n, changes) => n + changes.length, 0)
35	  );
36	
37	  function isDeviceKeyRoot(
38	    didDoc: Record<string, unknown>,
39	    deviceKeyId: string
40	  ): boolean | null {
41	    const rotationKeys = didDoc.rotationKeys;
42	    if (!Array.isArray(rotationKeys) || rotationKeys.length === 0) return null;
43	    return rotationKeys[0] === deviceKeyId;
44	  }
45	
46	  // Display the PDS host rather than the full URL ("bsky.social", not "https://bsky.social").
47	  function hostOf(url: string): string {
48	    try {
49	      return new URL(url).host;
50	    } catch {
51	      return url;
52	    }
53	  }
54	
55	  async function loadData() {
56	    loading = true;
57	    loadError = null;
58	    try {
59	      const dids = await listIdentities();
60	      identities = [];
61	      didDocs.clear();
62	
63	      for (const did of dids) {
64	        try {
65	          const [docResult, keyIdResult] = await Promise.all([
66	            getStoredDidDoc(did),
67	            getDeviceKeyId(did),
68	          ]);
69	
70	          const handle = docResult ? extractHandle(docResult) : null;
71	          const pdsUrl = docResult ? extractPdsFromPlcDoc(docResult) : null;
72	          const deviceKeyIsRoot = docResult ? isDeviceKeyRoot(docResult, keyIdResult) : null;
73	
74	          if (docResult) {
75	            didDocs.set(did, docResult);
76	          }
77	
78	          identities.push({
79	            did,
80	            handle,
81	            pdsUrl,
82	            deviceKeyIsRoot,
83	          });
84	        } catch (e) {
85	          console.error(`Failed to load identity ${did}:`, e);
86	          // Show degraded card instead of silently dropping the identity
87	          identities.push({
88	            did,
89	            handle: null,
90	            pdsUrl: null,
91	            deviceKeyIsRoot: null,
92	          });
93	        }
94	      }
95	    } catch (e) {
96	      console.error('Failed to load identities:', e);
97	      identities = [];
98	      didDocs.clear();
99	      loadError = 'Failed to load identities. Tap refresh to try again.';
100	    } finally {
101	      loading = false;
102	    }
103	  }
104	
105	  onMount(async () => {
106	    loadData();
107	
108	    // Fetch initial alert status
109	    checkIdentityStatus()
110	      .then((statuses) => {
111	        const data = new Map<string, UnauthorizedChange[]>();
112	        for (const s of statuses) {
113	          if (s.unauthorizedChanges.length > 0) data.set(s.did, s.unauthorizedChanges);
114	        }
115	        alertData = data;
116	      })
117	      .catch((e) => console.warn('Alert check failed:', e));
118	
119	    // Listen for plc_alert events from background monitoring timer
120	    unlisten = await listen<IdentityStatus[]>('plc_alert', (event) => {
121	      if (!Array.isArray(event.payload)) return;
122	      const data = new Map<string, UnauthorizedChange[]>();
123	      for (const s of event.payload) {
124	        if (s.unauthorizedChanges.length > 0) data.set(s.did, s.unauthorizedChanges);
125	      }
126	      alertData = data;
127	    });
128	  });
129	
130	  onDestroy(() => {
131	    unlisten?.();
132	  });
133	
134	  function getBadgeLabel(deviceKeyIsRoot: boolean | null): string {
135	    if (deviceKeyIsRoot === true) return 'Root key';
136	    if (deviceKeyIsRoot === false) return 'Not root';
137	    return 'Unknown';
138	  }
139	</script>
