2	  import { onMount } from 'svelte';
3	  import { loadHomeData, logOut, type HomeData } from '$lib/ipc';
4	  import DIDAvatar from './DIDAvatar.svelte';
5	  import Spinner from '$lib/components/ui/Spinner.svelte';
6	
7	  let {
8	    onnavdiddoc,
9	    onnavrecovery,
10	    onlogout,
11	  }: {
12	    onnavdiddoc: (data: HomeData) => void;
13	    onnavrecovery: (data: HomeData) => void;
14	    onlogout: () => void;
15	  } = $props();
16	
17	  let homeData = $state<HomeData | null>(null);
18	  let loading = $state(true);
19	  let didCopied = $state(false);
20	  let didCopyFailed = $state(false);
21	
22	  async function loadData() {
23	    loading = true;
24	    try {
25	      homeData = await loadHomeData();
26	    } catch {
27	      homeData = null;
28	    } finally {
29	      loading = false;
30	    }
31	  }
32	
33	  onMount(() => {
34	    loadData();
35	  });
36	
37	  // Truncate the DID for display on narrow mobile screens.
38	  // "did:plc:REDACTED" → "did:plc:abcdefgh…uvwxyz"
39	  let displayDid = $derived.by(() => {
40	    const did = homeData?.session?.did ?? '';
41	    const prefix = 'did:plc:';
42	    if (!did.startsWith(prefix)) return did;
43	    const specific = did.slice(prefix.length);
44	    if (specific.length < 14) return did;
45	    return `${prefix}${specific.slice(0, 8)}…${specific.slice(-6)}`;
46	  });
47	
48	  async function copyDid() {
49	    const did = homeData?.session?.did;
50	    if (!did) return;
51	    try {
52	      await navigator.clipboard.writeText(did);
53	      didCopied = true;
54	      setTimeout(() => { didCopied = false; }, 2000);
55	    } catch {
56	      didCopyFailed = true;
57	      setTimeout(() => { didCopyFailed = false; }, 2000);
58	    }
59	  }
60	
61	  async function handleLogOut() {
62	    try {
63	      await logOut();
64	    } catch {
65	      // logOut always succeeds on the Rust side; navigate away even if IPC fails
66	    }
67	    onlogout();
68	  }
