3	//! Per-DID identity storage layer with Keychain-based persistence.
4	//!
5	//! `IdentityStore` manages multi-identity lifecycle in the iOS Keychain:
6	//! - A top-level `"managed-dids"` entry maintains a JSON array index of all managed DIDs
7	//! - Per-DID prefixed entries store device keys, DID documents, and PLC audit logs
8	//! - Device keys are lazily generated on first access via `get_or_create_device_key`
9	//!
10	//! All Keychain operations use the shared `keychain::SERVICE` prefix.
11	
12	use crate::device_key::DevicePublicKey;
13	use serde::Serialize;
14	
15	// ── Constants ──────────────────────────────────────────────────────────────────
16	
17	const MANAGED_DIDS_ACCOUNT: &str = "managed-dids";
18	
19	// ── Error types ────────────────────────────────────────────────────────────────
20	
21	/// Errors returned by `IdentityStore` operations.
22	///
23	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE" }` — matches the
24	/// `CreateAccountError` and `DeviceKeyError` patterns.
25	#[derive(Debug, Serialize, thiserror::Error)]
26	#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")]
27	pub enum IdentityStoreError {
28	    #[error("identity not found")]
29	    IdentityNotFound,
30	    #[error("identity already exists")]
31	    IdentityAlreadyExists,
32	    #[error("keychain error: {message}")]
33	    KeychainError { message: String },
34	    #[error("key generation failed")]
35	    KeyGenerationFailed,
36	    #[error("serialization error: {message}")]
37	    SerializationError { message: String },
38	}
39	
40	// ── Per-DID account name helpers ───────────────────────────────────────────────
41	
42	/// Returns the Keychain account name for a DID's device key (private scalar).
43	fn device_key_account(did: &str) -> String {
44	    format!("{did}:device-key")
45	}
46	
47	/// Returns the Keychain account name for a DID's device key public key.
48	fn device_key_pub_account(did: &str) -> String {
49	    format!("{did}:device-key-pub")
50	}
51	
52	/// Returns the Keychain account name for a DID's device key SE app label.
53	fn device_key_app_label_account(did: &str) -> String {
54	    format!("{did}:device-key-app-label")
55	}
56	
57	/// Returns the Keychain account name for a DID's DID document.
58	fn did_doc_account(did: &str) -> String {
59	    format!("{did}:did-doc")
60	}
61	
62	/// Returns the Keychain account name for a DID's PLC audit log.
63	fn plc_log_account(did: &str) -> String {
64	    format!("{did}:plc-log")
65	}
66	
67	/// Returns the Keychain account name for a DID's OAuth tokens.
68	fn oauth_tokens_account(did: &str) -> String {
69	    format!("{did}:oauth-tokens")
70	}
71	
72	// ── IdentityStore ──────────────────────────────────────────────────────────────
73	
74	/// Unit struct for multi-identity Keychain management.
75	///
76	/// All methods are stateless — the Keychain is globally accessible.
77	/// Methods take `&self` to allow future phases to hold `IdentityStore` in `AppState`.
78	pub struct IdentityStore;
79	
80	impl IdentityStore {
81	    // ── Private helpers ────────────────────────────────────────────────────────
82	
83	    /// Load the current list of managed DIDs from the Keychain.
84	    ///
85	    /// Returns an empty list if the entry doesn't exist.
86	    /// Returns `Err` if the entry exists but contains invalid JSON (data corruption).
87	    fn load_managed_dids(&self) -> Result<Vec<String>, IdentityStoreError> {
88	        match crate::keychain::get_item(MANAGED_DIDS_ACCOUNT) {
89	            Ok(bytes) => serde_json::from_slice::<Vec<String>>(&bytes).map_err(|e| {
90	                tracing::error!(error = %e, "managed-dids Keychain entry contains invalid JSON");
91	                IdentityStoreError::SerializationError {
92	                    message: format!("failed to deserialize managed-dids: {e}"),
93	                }
94	            }),
95	            Err(e) if crate::keychain::is_not_found(&e) => Ok(vec![]),
96	            Err(e) => Err(IdentityStoreError::KeychainError {
97	                message: e.to_string(),
98	            }),
99	        }
100	    }
101	
102	    /// Save the managed DIDs list to the Keychain.
103	    fn save_managed_dids(&self, dids: &[String]) -> Result<(), IdentityStoreError> {
104	        let json =
105	            serde_json::to_vec(dids).map_err(|e| IdentityStoreError::SerializationError {
106	                message: format!("failed to serialize managed-dids: {e}"),
107	            })?;
108	        crate::keychain::store_item(MANAGED_DIDS_ACCOUNT, &json).map_err(|e| {
109	            IdentityStoreError::KeychainError {
110	                message: e.to_string(),
111	            }
112	        })
113	    }
114	
115	    /// Check whether a DID is in the managed list.
116	    ///
117	    /// Returns `Err` if a Keychain error occurs (propagates transient failures).
118	    fn is_managed(&self, did: &str) -> Result<bool, IdentityStoreError> {
119	        let dids = self.load_managed_dids()?;
120	        Ok(dids.contains(&did.to_string()))
121	    }
122	
123	    // ── Public API ─────────────────────────────────────────────────────────────
124	
125	    /// Register a new managed identity by DID.
126	    ///
127	    /// Appends the DID to the managed-dids index and saves it to the Keychain.
128	    /// Does NOT eagerly generate a device key — see [`Self::get_or_create_device_key`].
129	    ///
130	    /// Returns `Err(IdentityAlreadyExists)` if the DID is already registered.
131	    pub fn add_identity(&self, did: &str) -> Result<(), IdentityStoreError> {
132	        let mut dids = self.load_managed_dids()?;
133	
134	        if dids.contains(&did.to_string()) {
135	            return Err(IdentityStoreError::IdentityAlreadyExists);
136	        }
137	
138	        dids.push(did.to_string());
139	        self.save_managed_dids(&dids)?;
140	
141	        Ok(())
142	    }
143	
144	    /// Remove a managed identity and all associated Keychain entries.
145	    ///
146	    /// Updates the managed-dids index first, then performs best-effort deletion
147	    /// of all per-DID prefixed entries. Index-first ordering ensures that on
148	    /// partial failure the DID is unregistered (orphaned entries are benign)
149	    /// rather than registered-but-empty (confusing for callers).
150	    ///
151	    /// Returns `Err(IdentityNotFound)` if the DID is not in the managed list.
152	    pub fn remove_identity(&self, did: &str) -> Result<(), IdentityStoreError> {
153	        let mut dids = self.load_managed_dids()?;
154	
155	        if !dids.contains(&did.to_string()) {
156	            return Err(IdentityStoreError::IdentityNotFound);
157	        }
158	
159	        // Remove DID from index first — this is the authoritative state change.
160	        dids.retain(|d| d != did);
161	        self.save_managed_dids(&dids)?;
162	
163	        // Best-effort cleanup of per-DID Keychain entries. Not-found errors are
164	        // expected (entry may never have been created). Transient OS errors are
165	        // logged but do not fail the operation — the DID is already unregistered.
166	        let entries = [
167	            device_key_account(did),
168	            device_key_pub_account(did),
169	            device_key_app_label_account(did),
170	            did_doc_account(did),
171	            plc_log_account(did),
172	            oauth_tokens_account(did),
173	        ];
174	
