2	 * Utility functions for working with DID documents, especially PLC directory format.
3	 *
4	 * PLC directory format differs from W3C DID format:
5	 * - PLC uses "did" (W3C uses "id")
6	 * - PLC uses "services" as a map (W3C uses "service" as an array)
7	 * - PLC uses "rotationKeys" as a flat string array (W3C uses "verificationMethod" as an object array)
8	 * - PLC uses "verificationMethods" as a map (W3C uses "verificationMethod" as an object array)
9	 */
10	
11	/**
12	 * Extracts the PDS (Personal Data Server) endpoint from a PLC directory format DID document.
13	 *
14	 * PLC documents store services as a map with keys like "atproto_pds", where the value
15	 * has an "endpoint" field containing the PDS URL.
16	 *
17	 * @param doc - The DID document (loosely typed Record)
18	 * @returns The PDS endpoint URL, or null if not found or invalid
19	 */
20	export function extractPdsFromPlcDoc(doc: Record<string, unknown>): string | null {
21	  const services = doc.services;
22	  if (typeof services !== 'object' || services === null) return null;
23	
24	  const pds = (services as Record<string, unknown>).atproto_pds;
25	  if (typeof pds !== 'object' || pds === null) return null;
26	
27	  const endpoint = (pds as Record<string, unknown>).endpoint;
28	  return typeof endpoint === 'string' ? endpoint : null;
29	}
