31	/**
32	 * Extracts the handle from a PLC directory format DID document's alsoKnownAs array.
33	 * Strips the "at://" prefix from AT Protocol identifiers.
34	 *
35	 * @param doc - The DID document (loosely typed Record)
36	 * @returns The handle string (without at:// prefix), or null if not found
37	 */
38	export function extractHandle(doc: Record<string, unknown>): string | null {
39	  const alsoKnownAs = doc.alsoKnownAs;
40	  if (!Array.isArray(alsoKnownAs)) return null;
41	  for (const aka of alsoKnownAs) {
42	    if (typeof aka === 'string' && aka.startsWith('at://')) {
43	      return aka.slice(5);
44	    }
45	  }
46	  return null;
47	}
