49	/**
50	 * Truncates a did:plc identifier for display on narrow mobile screens.
51	 * "did:plc:REDACTED" → "did:plc:abcdefgh…stuvwx"
52	 *
53	 * @param did - The full DID string
54	 * @returns The truncated DID string, or the original if too short to truncate
55	 */
56	export function truncateDid(did: string): string {
57	  const prefix = 'did:plc:';
58	  if (!did.startsWith(prefix)) return did;
59	  const specific = did.slice(prefix.length);
60	  if (specific.length < 14) return did;
61	  return `${prefix}${specific.slice(0, 8)}…${specific.slice(-6)}`;
62	}
