77	/**
78	 * Normalizes a PLC directory format DID document to W3C format for DIDDocumentScreen.
79	 *
80	 * Converts:
81	 * - "did" → "id"
82	 * - "services" map → "service" array (each entry: {id, type, serviceEndpoint})
83	 * - "rotationKeys" string array → "verificationMethod" array (each entry: {id, type, publicKeyMultibase})
84	 * - "verificationMethods" map → appended to "verificationMethod" array (each entry: {id, type, publicKeyMultibase})
85	 * - "alsoKnownAs" passed through
86	 */
87	export function normalizePlcDocToW3c(plcDoc: Record<string, unknown>): Record<string, unknown> {
88	  const normalized: Record<string, unknown> = {
89	    id: plcDoc.did ?? plcDoc.id,
90	    alsoKnownAs: plcDoc.alsoKnownAs,
91	  };
92	
93	  // Convert services map to service array
94	  if (typeof plcDoc.services === 'object' && plcDoc.services !== null) {
95	    const servicesMap = plcDoc.services as Record<string, unknown>;
96	    const serviceArray: Array<Record<string, unknown>> = [];
97	
98	    for (const [key, value] of Object.entries(servicesMap)) {
99	      if (typeof value === 'object' && value !== null) {
100	        const serviceObj = value as Record<string, unknown>;
101	        serviceArray.push({
102	          id: `#${key}`,
103	          type: serviceObj.type,
104	          serviceEndpoint: serviceObj.endpoint,
105	        });
106	      }
107	    }
108	
109	    if (serviceArray.length > 0) {
110	      normalized.service = serviceArray;
111	    }
112	  }
113	
114	  // Convert rotationKeys array and verificationMethods map to verificationMethod array
115	  const verificationMethods: Array<Record<string, unknown>> = [];
116	
117	  if (Array.isArray(plcDoc.rotationKeys)) {
118	    for (let i = 0; i < plcDoc.rotationKeys.length; i++) {
119	      const key = plcDoc.rotationKeys[i];
120	      if (typeof key === 'string') {
121	        verificationMethods.push({
122	          id: `#rotation-${i}`,
123	          type: 'Multikey',
124	          publicKeyMultibase: key,
125	        });
126	      }
127	    }
128	  }
129	
130	  if (typeof plcDoc.verificationMethods === 'object' && plcDoc.verificationMethods !== null) {
131	    const vmMap = plcDoc.verificationMethods as Record<string, unknown>;
132	    for (const [key, value] of Object.entries(vmMap)) {
133	      if (typeof value === 'string') {
134	        verificationMethods.push({
135	          id: `#${key}`,
136	          type: 'Multikey',
137	          publicKeyMultibase: value,
138	        });
139	      }
140	    }
141	  }
142	
143	  if (verificationMethods.length > 0) {
144	    normalized.verificationMethod = verificationMethods;
145	  }
146	
147	  return normalized;
148	}
