324	        }
325	        Err(e) => {
326	            return Err(IdentityStoreError::KeychainError {
327	                message: e.to_string(),
328	            })
329	        }
330	    };
331	
332	    // Reconstruct the public key from stored private bytes.
333	    let signing_key =
334	        SigningKey::from_slice(&private_bytes).map_err(|e| {
335	            tracing::error!(did = did, error = %e, "stored device key bytes are not a valid P-256 scalar");
336	            IdentityStoreError::SerializationError {
337	                message: "invalid stored key bytes".into(),
338	            }
339	        })?;
340	    let encoded = signing_key.verifying_key().to_encoded_point(true); // compressed (33 bytes)
341	    let compressed = encoded.as_bytes();
342	    let multibase = multibase::encode(multibase::Base::Base58Btc, compressed);
343	
344	    // did:key requires the P-256 multicodec varint prefix [0x80, 0x24] (0x1200 as LEB128)
345	    // prepended to the compressed point. This matches crates/crypto/src/keys.rs
346	    // `P256_MULTICODEC_PREFIX = &[0x80, 0x24]`, which is `pub(crate)` and cannot be
347	    // imported across crate boundaries — the constant is duplicated intentionally.
348	    const P256_MULTICODEC: &[u8] = &[0x80, 0x24];
349	    let mut multikey = Vec::with_capacity(2 + compressed.len());
350	    multikey.extend_from_slice(P256_MULTICODEC);
351	    multikey.extend_from_slice(compressed);
352	    let key_id = format!(
353	        "did:key:{}",
354	        multibase::encode(multibase::Base::Base58Btc, &multikey)
355	    );
356	
357	    Ok(DevicePublicKey { multibase, key_id })
358	}
