360	#[cfg(all(target_os = "ios", not(target_env = "sim")))]
361	fn get_or_create_per_did_device_key(did: &str) -> Result<DevicePublicKey, IdentityStoreError> {
362	    use security_framework::{
363	        access_control::{ProtectionMode, SecAccessControl},
364	        item::Location,
365	        key::{GenerateKeyOptions, KeyType, SecKey, Token},
366	    };
367	
368	    let pub_account = device_key_pub_account(did);
369	    let label_account = device_key_app_label_account(did);
370	
371	    // Fast path: check both metadata accounts — if both present, return cached public key.
372	    // This avoids SE hardware interaction on every call after first generation.
373	    match (
374	        crate::keychain::get_item(&pub_account),
375	        crate::keychain::get_item(&label_account),
376	    ) {
377	        (Ok(compressed), Ok(_)) => {
378	            // Both present — fast path. Return the cached public key.
379	            let multibase = multibase::encode(multibase::Base::Base58Btc, &compressed);
380	            // did:key requires the P-256 multicodec varint prefix [0x80, 0x24] (0x1200 as LEB128).
381	            const P256_MULTICODEC: &[u8] = &[0x80, 0x24];
382	            let mut multikey = Vec::with_capacity(2 + compressed.len());
383	            multikey.extend_from_slice(P256_MULTICODEC);
384	            multikey.extend_from_slice(&compressed);
385	            let key_id = format!(
386	                "did:key:{}",
387	                multibase::encode(multibase::Base::Base58Btc, &multikey)
388	            );
389	            return Ok(DevicePublicKey { multibase, key_id });
390	        }
391	        (Err(e), _) | (_, Err(e)) if !crate::keychain::is_not_found(&e) => {
392	            // Transient OS error — do not fall through to generation.
393	            return Err(IdentityStoreError::KeychainError {
394	                message: e.to_string(),
395	            });
396	        }
397	        _ => {
398	            // One or both missing — fall through to generate.
399	        }
400	    }
401	
402	    // Generate a new SE-backed P-256 key.
403	    // set_location(DataProtectionKeychain) is required — without it, security_framework sets
404	    // kSecAttrIsPermanent = false, meaning the key is not persisted to the Keychain and will
405	    // not survive app restart.
406	    // set_access_control with PRIVATE_KEY_USAGE is required for SE keys — the SE enforces
407	    // that only explicitly-authorized operations can use the private key for signing.
408	    // The PRIVATE_KEY_USAGE flag is kSecAccessControlPrivateKeyUsage = 1 << 30.
409	    let access_control = SecAccessControl::create_with_protection(
410	        Some(ProtectionMode::AccessibleWhenUnlockedThisDeviceOnly),
411	        1 << 30, // kSecAccessControlPrivateKeyUsage
412	    )
413	    .map_err(|e| {
414	        tracing::error!(did = did, error = %e, "SecAccessControl creation failed");
415	        IdentityStoreError::KeyGenerationFailed
416	    })?;
417	
418	    let mut opts = GenerateKeyOptions::default();
419	    opts.set_key_type(KeyType::ec())
420	        .set_size_in_bits(256)
421	        .set_token(Token::SecureEnclave)
422	        .set_label(&format!("ezpds-device-key-{did}"))
423	        .set_location(Location::DataProtectionKeychain)
424	        .set_access_control(access_control); // takes ownership (by value)
425	
426	    let priv_key = SecKey::new(&opts).map_err(|e| {
427	        tracing::error!(did = did, error = %e, "Secure Enclave key generation failed");
428	        IdentityStoreError::KeyGenerationFailed
429	    })?;
430	
431	    // Retrieve the public key and its external representation.
432	    // SecKeyCopyExternalRepresentation on the *public* key returns the uncompressed
433	    // 65-byte X9.62 point (0x04 || x[32] || y[32]).
434	    let pub_key = priv_key
435	        .public_key()
436	        .ok_or(IdentityStoreError::KeyGenerationFailed)?;
437	    let pub_repr = pub_key
438	        .external_representation()
439	        .ok_or(IdentityStoreError::KeyGenerationFailed)?;
440	    let uncompressed: Vec<u8> = pub_repr.to_vec(); // 65 bytes
441	
442	    // Compress: prefix byte = 0x02 (even y) or 0x03 (odd y); keep x[32].
443	    // The last byte of the y coordinate determines parity.
444	    let mut compressed = [0u8; 33];
445	    compressed[0] = if uncompressed[64] & 1 == 0 {
446	        0x02
447	    } else {
448	        0x03
449	    };
450	    compressed[1..].copy_from_slice(&uncompressed[1..33]);
451	
452	    // Store the compressed public key for the fast path on future calls.
453	    crate::keychain::store_item(&pub_account, &compressed).map_err(|e| {
454	        IdentityStoreError::KeychainError {
455	            message: e.to_string(),
456	        }
457	    })?;
458	
459	    // Get and store application_label. Roll back pub_account if this fails.
460	    let app_label = priv_key.application_label().ok_or_else(|| {
461	        tracing::error!(
462	            did = did,
463	            "SE key created but application_label returned None"
464	        );
465	        let _ = crate::keychain::delete_item(&pub_account);
466	        IdentityStoreError::KeychainError {
467	            message: "SE key created but application_label returned None; do not retry".into(),
468	        }
469	    })?;
470	    crate::keychain::store_item(&label_account, &app_label).map_err(|e| {
471	        let _ = crate::keychain::delete_item(&pub_account);
472	        IdentityStoreError::KeychainError {
473	            message: e.to_string(),
474	        }
475	    })?;
476	
477	    let multibase = multibase::encode(multibase::Base::Base58Btc, &compressed);
478	    // did:key requires the P-256 multicodec varint prefix [0x80, 0x24] (0x1200 as LEB128).
479	    const P256_MULTICODEC: &[u8] = &[0x80, 0x24];
480	    let mut multikey = Vec::with_capacity(2 + compressed.len());
481	    multikey.extend_from_slice(P256_MULTICODEC);
482	    multikey.extend_from_slice(&compressed);
483	    let key_id = format!(
484	        "did:key:{}",
485	        multibase::encode(multibase::Base::Base58Btc, &multikey)
486	    );
487	    Ok(DevicePublicKey { multibase, key_id })
488	}
