22	/// Errors returned by device key operations.
23	///
24	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE" }` — matches the
25	/// `CreateAccountError` pattern in `lib.rs`.
26	#[derive(Debug, Serialize, thiserror::Error)]
27	#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")]
28	pub enum DeviceKeyError {
29	    #[error("key generation failed")]
30	    KeyGenerationFailed,
31	    #[error("key not found; call get_or_create before sign")]
32	    KeyNotFound,
33	    #[error("signing failed")]
34	    SigningFailed,
35	    /// DER → r||s parse failed (SE path only; not reachable on simulator).
36	    #[error("invalid signature encoding")]
37	    InvalidSignature,
38	    #[error("keychain error: {message}")]
39	    KeychainError { message: String },
40	}
