42	// ── Simulator / macOS host path ───────────────────────────────────────────────
43	//
44	// Covers:
45	//   - macOS (target_os = "macos"): used for `cargo test` on developer machines
46	//   - iOS Simulator (target_os = "ios", target_env = "sim"): no Secure Enclave hardware
47	//
48	// Note: the design doc cfg (all(target_vendor = "apple", target_env = "sim")) does not
49	// match macOS host where target_env = "". We extend to include target_os = "macos" so
50	// that `cargo test` exercises the software path rather than the SE stubs below.
51	
52	#[cfg(any(target_os = "macos", all(target_os = "ios", target_env = "sim")))]
53	pub fn get_or_create() -> Result<DevicePublicKey, DeviceKeyError> {
54	    use p256::ecdsa::SigningKey;
55	
56	    const ACCOUNT: &str = "device-rotation-key-priv";
57	
58	    // Try to load existing private key bytes from Keychain.
59	    let private_bytes: Vec<u8> = match crate::keychain::get_item(ACCOUNT) {
60	        Ok(bytes) => bytes,
61	        Err(_) => {
62	            // No key yet — generate a new P-256 keypair via the crypto crate.
63	            let keypair =
64	                crypto::generate_p256_keypair().map_err(|_| DeviceKeyError::KeyGenerationFailed)?;
65	            // to_vec(): Deref gives &[u8; 32], coerces to &[u8], allocates into Vec<u8>.
66	            let bytes = keypair.private_key_bytes.to_vec();
67	            crate::keychain::store_item(ACCOUNT, &bytes).map_err(|e| {
68	                DeviceKeyError::KeychainError {
69	                    message: e.to_string(),
70	                }
71	            })?;
72	            bytes
73	        }
74	    };
75	
76	    // Reconstruct the public key from stored private bytes.
77	    let signing_key =
78	        SigningKey::from_slice(&private_bytes).map_err(|_| DeviceKeyError::KeychainError {
79	            message: "invalid stored key bytes".into(),
80	        })?;
81	    let encoded = signing_key.verifying_key().to_encoded_point(true); // compressed (33 bytes)
82	    let compressed = encoded.as_bytes();
83	    let multibase = multibase::encode(multibase::Base::Base58Btc, compressed);
84	    // did:key requires the P-256 multicodec varint prefix [0x80, 0x24] (0x1200 as LEB128)
85	    // prepended to the compressed point. This matches crates/crypto/src/keys.rs
86	    // `P256_MULTICODEC_PREFIX = &[0x80, 0x24]`, which is `pub(crate)` and cannot be
87	    // imported across crate boundaries — the constant is duplicated intentionally.
88	    const P256_MULTICODEC: &[u8] = &[0x80, 0x24];
89	    let mut multikey = Vec::with_capacity(2 + compressed.len());
90	    multikey.extend_from_slice(P256_MULTICODEC);
91	    multikey.extend_from_slice(compressed);
92	    let key_id = format!(
93	        "did:key:{}",
94	        multibase::encode(multibase::Base::Base58Btc, &multikey)
95	    );
96	
97	    Ok(DevicePublicKey { multibase, key_id })
98	}
