100	#[cfg(any(target_os = "macos", all(target_os = "ios", target_env = "sim")))]
101	pub fn sign(data: &[u8]) -> Result<Vec<u8>, DeviceKeyError> {
102	    use p256::ecdsa::signature::Signer;
103	    use p256::ecdsa::{Signature, SigningKey};
104	
105	    const ACCOUNT: &str = "device-rotation-key-priv";
106	
107	    // If the key doesn't exist, signal that get_or_create must be called first.
108	    // Distinguish ItemNotFound from other OS errors.
109	    let private_bytes = crate::keychain::get_item(ACCOUNT).map_err(|e| {
110	        if crate::keychain::is_not_found(&e) {
111	            DeviceKeyError::KeyNotFound
112	        } else {
113	            DeviceKeyError::KeychainError {
114	                message: e.to_string(),
115	            }
116	        }
117	    })?;
118	
119	    let signing_key =
120	        SigningKey::from_slice(&private_bytes).map_err(|_| DeviceKeyError::SigningFailed)?;
121	
122	    // sign() uses the deterministic Signer impl (RFC 6979 nonce).
123	    // It internally hashes `data` with SHA-256 before signing.
124	    let signature: Signature = signing_key.sign(data);
125	
126	    // Normalize to low-S form. ATProto/PLC directory requires low-S ECDSA
127	    // signatures; without this, roughly half of all signatures would be
128	    // rejected by the PLC directory even though they are mathematically valid.
129	    // normalize_s() returns Some(normalized) if s was high, None if already low.
130	    let signature = signature.normalize_s().unwrap_or(signature);
131	
132	    // to_bytes() returns a fixed 64-byte GenericArray<u8, U64> (raw r||s).
133	    Ok(signature.to_bytes().to_vec())
134	}
