136	// ── Real device (Secure Enclave) path ────────────────────────────────────────
137	//
138	// The SE private key is permanent and non-extractable; the public key and
139	// application_label (SHA1 hash) are stored in the regular Keychain for lookup.
140	
141	/// Account names used to store SE key metadata in the regular Keychain.
142	/// The SE private key itself is stored in the Secure Enclave and never leaves it.
143	#[cfg(all(target_os = "ios", not(target_env = "sim")))]
144	const SE_PUB_ACCOUNT: &str = "device-rotation-key-pub";
145	#[cfg(all(target_os = "ios", not(target_env = "sim")))]
146	const SE_APP_LABEL_ACCOUNT: &str = "device-rotation-key-app-label";
147	
148	#[cfg(all(target_os = "ios", not(target_env = "sim")))]
149	pub fn get_or_create() -> Result<DevicePublicKey, DeviceKeyError> {
150	    // Fast path: if we already stored the compressed public key and app_label, return it directly.
151	    // This avoids SE hardware interaction on every call after first generation.
152	    // Check BOTH SE_PUB_ACCOUNT and SE_APP_LABEL_ACCOUNT to ensure state consistency.
153	    match (
154	        crate::keychain::get_item(SE_PUB_ACCOUNT),
155	        crate::keychain::get_item(SE_APP_LABEL_ACCOUNT),
156	    ) {
157	        (Ok(compressed), Ok(_)) => {
158	            // Both present — fast path. Return the cached public key.
159	            let multibase = multibase::encode(multibase::Base::Base58Btc, &compressed);
160	            // did:key requires the P-256 multicodec varint prefix [0x80, 0x24] (0x1200 as LEB128).
161	            const P256_MULTICODEC: &[u8] = &[0x80, 0x24];
162	            let mut multikey = Vec::with_capacity(2 + compressed.len());
163	            multikey.extend_from_slice(P256_MULTICODEC);
164	            multikey.extend_from_slice(&compressed);
165	            let key_id = format!(
166	                "did:key:{}",
167	                multibase::encode(multibase::Base::Base58Btc, &multikey)
168	            );
169	            return Ok(DevicePublicKey { multibase, key_id });
170	        }
171	        (Err(e), _) | (_, Err(e)) if !crate::keychain::is_not_found(&e) => {
172	            // Transient OS error — do not fall through to generation.
173	            return Err(DeviceKeyError::KeychainError {
174	                message: e.to_string(),
175	            });
176	        }
177	        _ => {
178	            // One or both missing — fall through to generate.
179	        }
180	    }
181	
182	    // Generate a new SE-backed P-256 key.
183	    // set_location(DataProtectionKeychain) is required — without it, security_framework sets
184	    // kSecAttrIsPermanent = false, meaning the key is not persisted to the Keychain and will
185	    // not survive app restart.
186	    // set_access_control with PRIVATE_KEY_USAGE is required for SE keys — the SE enforces
187	    // that only explicitly-authorized operations can use the private key for signing.
188	    // The PRIVATE_KEY_USAGE flag is kSecAccessControlPrivateKeyUsage = 1 << 30.
189	    let access_control = SecAccessControl::create_with_protection(
190	        Some(ProtectionMode::AccessibleWhenUnlockedThisDeviceOnly),
191	        1 << 30, // kSecAccessControlPrivateKeyUsage
192	    )
193	    .map_err(|_| DeviceKeyError::KeyGenerationFailed)?;
194	
195	    let mut opts = GenerateKeyOptions::default();
196	    opts.set_key_type(KeyType::ec())
197	        .set_size_in_bits(256)
198	        .set_token(Token::SecureEnclave)
199	        .set_label("ezpds-device-rotation-key")
200	        .set_location(Location::DataProtectionKeychain)
201	        .set_access_control(access_control); // takes ownership (by value)
202	
203	    let priv_key = SecKey::new(&opts).map_err(|_| DeviceKeyError::KeyGenerationFailed)?;
204	
205	    // Retrieve the public key and its external representation.
206	    // SecKeyCopyExternalRepresentation on the *public* key returns the uncompressed
207	    // 65-byte X9.62 point (0x04 || x[32] || y[32]).
208	    let pub_key = priv_key
209	        .public_key()
210	        .ok_or(DeviceKeyError::KeyGenerationFailed)?;
211	    let pub_repr = pub_key
212	        .external_representation()
213	        .ok_or(DeviceKeyError::KeyGenerationFailed)?;
214	    let uncompressed: Vec<u8> = pub_repr.to_vec(); // 65 bytes
215	
216	    // Compress: prefix byte = 0x02 (even y) or 0x03 (odd y); keep x[32].
217	    // The last byte of the y coordinate determines parity.
218	    let mut compressed = [0u8; 33];
219	    compressed[0] = if uncompressed[64] & 1 == 0 {
220	        0x02
221	    } else {
222	        0x03
223	    };
224	    compressed[1..].copy_from_slice(&uncompressed[1..33]);
225	
226	    // Store the compressed public key for the fast path on future calls.
227	    crate::keychain::store_item(SE_PUB_ACCOUNT, &compressed).map_err(|e| {
228	        DeviceKeyError::KeychainError {
229	            message: e.to_string(),
230	        }
231	    })?;
232	
233	    // Get and store application_label. Roll back SE_PUB_ACCOUNT if this fails.
234	    let app_label = priv_key.application_label().ok_or_else(|| {
235	        let _ = crate::keychain::delete_item(SE_PUB_ACCOUNT);
236	        DeviceKeyError::KeychainError {
237	            message: "SE key created but application_label returned None; do not retry".into(),
238	        }
239	    })?;
240	    crate::keychain::store_item(SE_APP_LABEL_ACCOUNT, &app_label).map_err(|e| {
241	        let _ = crate::keychain::delete_item(SE_PUB_ACCOUNT);
242	        DeviceKeyError::KeychainError {
243	            message: e.to_string(),
244	        }
245	    })?;
246	
247	    let multibase = multibase::encode(multibase::Base::Base58Btc, &compressed);
248	    // did:key requires the P-256 multicodec varint prefix [0x80, 0x24] (0x1200 as LEB128).
249	    const P256_MULTICODEC: &[u8] = &[0x80, 0x24];
250	    let mut multikey = Vec::with_capacity(2 + compressed.len());
251	    multikey.extend_from_slice(P256_MULTICODEC);
252	    multikey.extend_from_slice(&compressed);
253	    let key_id = format!(
254	        "did:key:{}",
255	        multibase::encode(multibase::Base::Base58Btc, &multikey)
256	    );
257	    Ok(DevicePublicKey { multibase, key_id })
258	}
