260	#[cfg(all(target_os = "ios", not(target_env = "sim")))]
261	pub fn sign(data: &[u8]) -> Result<Vec<u8>, DeviceKeyError> {
262	    use p256::ecdsa::Signature;
263	
264	    // Load the application_label to look up the SE private key.
265	    let app_label =
266	        crate::keychain::get_item(SE_APP_LABEL_ACCOUNT).map_err(|_| DeviceKeyError::KeyNotFound)?;
267	
268	    // Find the SE private key in the Keychain by its application_label.
269	    // load_refs(true) returns SearchResult::Ref(CFType) containing the SecKeyRef.
270	    let mut search = ItemSearchOptions::new();
271	    search
272	        .class(ItemClass::key())
273	        .key_class(KeyClass::private())
274	        .application_label(&app_label)
275	        .load_refs(true)
276	        .limit(1);
277	
278	    let results = search.search().map_err(|e| DeviceKeyError::KeychainError {
279	        message: e.to_string(),
280	    })?;
281	
282	    // Extract the SecKey from the typed Reference result.
283	    // SearchResult::Ref wraps a Reference enum; Reference::Key holds the already-wrapped SecKey.
284	    // No unsafe code is needed — security_framework handles the SecKeyRef wrapping internally.
285	    let sec_key = match results.into_iter().next() {
286	        Some(SearchResult::Ref(Reference::Key(key))) => key,
287	        _ => return Err(DeviceKeyError::KeyNotFound),
288	    };
289	
290	    // create_signature uses REDACTED.
291	    // The SE hashes `data` with SHA-256 internally before signing.
292	    // Returns DER-encoded ECDSA signature (70–72 bytes).
293	    let der_sig = sec_key
294	        .create_signature(Algorithm::ECDSASignatureMessageX962SHA256, data)
295	        .map_err(|_| DeviceKeyError::SigningFailed)?;
296	
297	    // Convert DER to raw 64-byte r||s (the format expected by ATProto/did:plc).
298	    // from_der() is a pure parser — it does NOT normalize low-S. Apple's SE may return
299	    // high-S signatures. normalize_s() returns None if already low-S (no-op), Some(normalized) if high-S was reduced.
300	    let sig = Signature::from_der(&der_sig).map_err(|_| DeviceKeyError::InvalidSignature)?;
301	    let sig = sig.normalize_s().unwrap_or(sig);
302	    Ok(sig.to_bytes().to_vec())
303	}
